import com.mirrorlink.mobile.AdaptiveQuality;
public class AdaptiveQualityTest {public static void main(String[] args){AdaptiveQuality a=new AdaptiveQuality(120,2560,"balanced");if(a.decide(7000,120,2560,400,8,3,false)!=0||a.decide(8000,120,2560,400,8,3,false)!=0||a.decide(9000,120,2560,400,8,3,false)!=-1)throw new AssertionError("congestion");if(a.decide(10000,96,2048,400,8,3,false)!=0)throw new AssertionError("cooldown");for(int i=0;i<14;i++)if(a.decide(16000+i*1000,96,2048,60,0,0,false)!=0)throw new AssertionError("slow recovery");if(a.decide(30000,96,2048,60,0,0,false)!=1)throw new AssertionError("recovery");if(new AdaptiveQuality(1,640,"flow").lowerFps(1)!=1)throw new AssertionError("user ceiling");System.out.println("PASS adaptive hysteresis and ceiling");}}
